-- On user confirmation, create or update profiles and set status to PENDING_MODERATION
WITH u AS (SELECT id as user_id FROM users WHERE telegram_id = {{$json["telegram_id"]}}), s AS (SELECT ai_context FROM profile_ai_sessions WHERE user_id = (SELECT user_id FROM u) AND session_status = 'IN_PROGRESS' ORDER BY created_at DESC LIMIT 1)
INSERT INTO profiles (user_id, display_name, age, city, description, avatar_file_id, status, moderation_status) SELECT (SELECT user_id FROM u), (s.ai_context->>'display_name')::text, (s.ai_context->>'age')::int, (s.ai_context->>'city')::text, (s.ai_context->>'description')::text, (s.ai_context->>'avatar_file_id')::text, 'PENDING_MODERATION', 'PENDING' WHERE NOT EXISTS (SELECT 1 FROM profiles p JOIN u ON p.user_id = u.user_id);
